<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes de auditoría | APM</title><?php require ROOT.'/shared/head_assets.php'; ?>
<style>.audit-filter{display:grid;grid-template-columns:1fr 1fr minmax(220px,1.4fr) auto;gap:12px;align-items:end}.audit-filter label{display:grid;gap:6px;font-size:.75rem;font-weight:800;color:var(--ink-600);letter-spacing:.06em}.audit-filter input,.audit-filter select{height:43px;border:1px solid var(--line);border-radius:10px;padding:0 12px;font:inherit;background:#fff}.audit-metrics{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin:18px 0}.audit-metric{background:#fff;border:1px solid var(--line);border-radius:15px;padding:17px;border-top:4px solid var(--ocean-700)}.audit-metric span{font-size:.72rem;color:var(--ink-600);text-transform:uppercase;letter-spacing:.08em}.audit-metric strong{display:block;font-size:1.7rem;color:var(--navy-900);margin-top:4px}.audit-layout{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(290px,.55fr);gap:18px}.action-list{display:grid;gap:11px}.action-item{display:grid;grid-template-columns:minmax(120px,1fr) 2fr 60px;gap:10px;align-items:center;font-size:.8rem}.action-bar{height:9px;background:#edf4f7;border-radius:99px;overflow:hidden}.action-fill{height:100%;background:linear-gradient(90deg,var(--ocean-700),var(--teal-500));border-radius:99px}.audit-user-link{color:var(--ocean-700);font-weight:800;text-decoration:none}@media(max-width:1050px){.audit-metrics{grid-template-columns:repeat(3,1fr)}.audit-layout{grid-template-columns:1fr}}@media(max-width:700px){.audit-filter{grid-template-columns:1fr}.audit-metrics{grid-template-columns:1fr 1fr}}</style></head><body>
<div id="overlay" class="overlay" onclick="closeSidebar()"></div><button class="sidebar-open-btn" id="sidebarOpenBtn" onclick="openSidebar()" aria-label="Abrir menú"><i class="bi bi-layout-sidebar"></i></button><div class="app"><?php require ROOT.'/shared/menu.php'; ?><section class="content"><?php $topbarSubtitle='Auditoría y Control';$topbarShowSearch=true;require ROOT.'/shared/topbar.php'; ?><main class="main"><div class="content-shell">
<section class="hero"><div><div class="hero-kicker">Trazabilidad · Informe institucional</div><h2><?= $usuario!==''?'Auditoría por usuario':'Reporte general de auditoría' ?></h2><p><?= $usuario!==''?'Actividad exacta registrada para '.htmlspecialchars($usuario).'.':'Resumen de accesos, alertas, módulos y acciones realizadas por los usuarios.' ?></p><div class="hero-actions"><a class="btn btn-primary" href="<?= BASE_URL ?>/auditoria/reportes/exportar?<?= http_build_query(compact('desde','hasta','usuario')) ?>"><i class="bi bi-download"></i> Exportar CSV</a><a class="btn btn-outline" href="<?= BASE_URL ?>/auditoria/logs"><i class="bi bi-journal-text"></i> Ver bitácora completa</a></div></div></section>
<section class="card" style="padding:18px;margin-bottom:18px"><form class="audit-filter" method="get" action="<?= BASE_URL ?>/auditoria/reportes"><label>DESDE<input type="date" name="desde" value="<?= htmlspecialchars($desde) ?>"></label><label>HASTA<input type="date" name="hasta" value="<?= htmlspecialchars($hasta) ?>"></label><label>USUARIO<select name="usuario"><option value="">Todos los usuarios</option><?php foreach($usuarios as $u): ?><option value="<?= htmlspecialchars($u) ?>" <?= $usuario===$u?'selected':'' ?>><?= htmlspecialchars($u) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary" type="submit"><i class="bi bi-funnel"></i> Generar reporte</button></form></section>
<div class="audit-metrics"><div class="audit-metric"><span>Eventos</span><strong><?= (int)($resumen['total_eventos']??0) ?></strong></div><div class="audit-metric"><span>Usuarios</span><strong><?= (int)($resumen['usuarios']??0) ?></strong></div><div class="audit-metric" style="border-top-color:#10b981"><span>Accesos exitosos</span><strong><?= (int)($resumen['accesos']??0) ?></strong></div><div class="audit-metric" style="border-top-color:#ef4444"><span>Alertas</span><strong><?= (int)($resumen['alertas']??0) ?></strong></div><div class="audit-metric" style="border-top-color:#8b5cf6"><span>Módulos</span><strong><?= (int)($resumen['modulos']??0) ?></strong></div></div>
<div class="audit-layout"><section class="card table-card"><div class="card-header"><div><h3><i class="bi bi-people"></i> Actividad por usuario</h3><p>Seleccione un usuario para abrir su reporte individual.</p></div></div><div class="table-wrap"><table id="auditoriaUsuariosTable" data-apm-datatable data-dt-page-length="10" data-dt-order='[[1,"desc"]]' data-dt-search-placeholder="Buscar usuario…" data-dt-empty="No existen eventos para el período seleccionado."><thead><tr><th>Usuario</th><th>Eventos</th><th>Accesos</th><th>Alertas</th><th>Módulos</th><th>Última actividad</th></tr></thead><tbody><?php foreach($porUsuario as $row): ?><tr><td><a class="audit-user-link" href="?<?= http_build_query(['desde'=>$desde,'hasta'=>$hasta,'usuario'=>$row['usuario']]) ?>"><?= htmlspecialchars($row['usuario']) ?></a></td><td><?= (int)$row['total_eventos'] ?></td><td><?= (int)$row['accesos'] ?></td><td><span class="badge <?= (int)$row['alertas']>0?'badge-danger':'badge-active' ?>"><?= (int)$row['alertas'] ?></span></td><td><?= (int)$row['modulos'] ?></td><td data-order="<?= htmlspecialchars((string)$row['ultima_actividad']) ?>"><?= htmlspecialchars((string)$row['ultima_actividad']) ?></td></tr><?php endforeach; ?><?php if(!$porUsuario): ?><tr data-dt-empty><td colspan="6">No existen eventos para el período seleccionado.</td></tr><?php endif; ?></tbody></table></div></section>
<aside class="card" style="padding:20px"><h3><i class="bi bi-bar-chart"></i> Acciones frecuentes</h3><div class="action-list"><?php $max=max(1,...array_map(fn($a)=>(int)$a['cantidad'],$acciones));foreach($acciones as $a): ?><div class="action-item"><span><?= htmlspecialchars($a['accion']) ?></span><div class="action-bar"><div class="action-fill" style="width:<?= round((int)$a['cantidad']/$max*100) ?>%"></div></div><strong><?= (int)$a['cantidad'] ?></strong></div><?php endforeach; ?></div></aside></div>
<section class="card table-card" style="margin-top:18px"><div class="card-header"><div><h3><i class="bi bi-clock-history"></i> Eventos recientes</h3><p>Detalle de los últimos 100 eventos del filtro.</p></div></div><div class="table-wrap"><table id="auditoriaEventosTable" data-apm-datatable data-dt-page-length="25" data-dt-order='[[0,"desc"]]' data-dt-search-placeholder="Buscar usuario, módulo, acción o IP…" data-dt-empty="No existen eventos recientes."><thead><tr><th>Fecha</th><th>Usuario</th><th>Módulo</th><th>Acción</th><th>Detalle</th><th>IP</th></tr></thead><tbody><?php foreach($eventos as $e): ?><tr><td data-order="<?= htmlspecialchars((string)$e['fecha_hora']) ?>" style="white-space:nowrap"><?= htmlspecialchars((string)$e['fecha_hora']) ?></td><td><?= htmlspecialchars($e['usuario']) ?></td><td><?= htmlspecialchars($e['modulo']) ?></td><td><code><?= htmlspecialchars($e['accion']) ?></code></td><td><?= htmlspecialchars((string)$e['descripcion_detalle']) ?></td><td><?= htmlspecialchars((string)$e['direccion_ip']) ?></td></tr><?php endforeach; ?><?php if(!$eventos): ?><tr data-dt-empty><td colspan="6">No existen eventos recientes.</td></tr><?php endif; ?></tbody></table></div></section>
</div></main></section></div><?php require ROOT.'/shared/footer_scripts.php'; ?></body></html>
